import re
def clean_tag_text(text):
    return re.sub(r'<[^>]*>', ' ', text)

def get_words_count(text_list):
    count = 0
    for t in text_list:
        clean_text = clean_tag_text(t)
        count += len(clean_text.split())
    return count

